def route_stations(n, pipes, s, r):
    forward = [[] for _ in range(n)]
    backward = [[] for _ in range(n)]
    for a, b in pipes:
        forward[a].append(b)
        backward[b].append(a)

    def reach(adj, start):
        seen = [False] * n
        seen[start] = True
        stack = [start]
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if not seen[y]:
                    seen[y] = True
                    stack.append(y)
        return seen

    from_s = reach(forward, s)
    to_r = reach(backward, r)
    return [v for v in range(n) if from_s[v] and to_r[v]]
